#### 4.3.1 North-South API Example: E-Commerce Customer API

**Scenario**: A customer management API that serves both web and mobile applications for an e-commerce platform.

**Implementation Characteristics**:

- External consumers (web browsers, mobile apps)
- User authentication required
- Public API documentation needed
- Rate limiting to prevent abuse
- Cross-security boundary (DMZ to internal network)

```javascript
// North-South API Implementation Example
const express = require('express');
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');

const app = express();

// Security middleware for North-South APIs
app.use(helmet());
app.use(express.json({ limit: '10mb' }));

// Rate limiting for external consumers
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
});
app.use('/api/v1/', limiter);

// JWT authentication middleware
const authenticateToken = (req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) {
        return res.status(401).json({
            error: 'Access token required',
            errorCode: 'AUTH_TOKEN_MISSING',
        });
    }

    jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
        if (err) {
            return res.status(403).json({
                error: 'Invalid access token',
                errorCode: 'AUTH_TOKEN_INVALID',
            });
        }
        req.user = user;
        next();
    });
};

// North-South API endpoint
app.get('/api/v1/customers', authenticateToken, async (req, res) => {
    try {
        const { page = 1, limit = 20 } = req.query;
        const offset = (page - 1) * limit;

        // Business logic with user context
        const customers = await customerService.getCustomersForUser(req.user.id, { offset, limit });

        // User-friendly response format
        res.json({
            data: customers.map((customer) => ({
                id: customer.id,
                name: customer.name,
                email: customer.email,
                createdAt: customer.createdAt,
            })),
            meta: {
                page: parseInt(page),
                limit: parseInt(limit),
                total: customers.length,
                hasNextPage: customers.length === parseInt(limit),
            },
        });
    } catch (error) {
        console.error('North-South API Error:', error);
        res.status(500).json({
            error: 'Internal server error',
            errorCode: 'INTERNAL_ERROR',
            requestId: req.id,
        });
    }
});

// Health check endpoint for load balancers
app.get('/health', (req, res) => {
    res.status(200).json({ status: 'healthy', timestamp: new Date().toISOString() });
});

app.listen(3000, () => {
    console.log('North-South API server running on port 3000');
});
```

