#### 4.3.2 East-West API Example: Internal Customer Service

**Scenario**: An internal microservice that provides customer data to other services within the same cluster.

**Implementation Characteristics**:

- Service-to-service communication only
- mTLS authentication
- High-performance requirements
- Internal service contracts
- Within same trust boundary

```javascript
// East-West API Implementation Example
const express = require('express');
const fs = require('fs');
const https = require('https');
const promClient = require('prom-client');

const app = express();

// Metrics collection for service mesh
const register = new promClient.Registry();
const httpRequestDuration = new promClient.Histogram({
    name: 'http_request_duration_seconds',
    help: 'Duration of HTTP requests in seconds',
    labelNames: ['method', 'route', 'status_code', 'calling_service'],
});
register.registerMetric(httpRequestDuration);

app.use(express.json());

// Service identity middleware
const authenticateService = (req, res, next) => {
    const clientCert = req.connection.getPeerCertificate();

    if (!clientCert || !clientCert.subject) {
        return res.status(401).json({
            error: 'Client certificate required',
            errorCode: 'SERVICE_CERT_MISSING',
            traceId: req.headers['x-trace-id'],
        });
    }

    // Extract service identity from certificate
    const serviceIdentity = clientCert.subject.CN;
    const allowedServices = [
        'order-service.production.svc.cluster.local',
        'notification-service.production.svc.cluster.local',
        'analytics-service.production.svc.cluster.local',
    ];

    if (!allowedServices.includes(serviceIdentity)) {
        return res.status(403).json({
            error: 'Service not authorized',
            errorCode: 'SERVICE_NOT_AUTHORIZED',
            traceId: req.headers['x-trace-id'],
        });
    }

    req.callingService = serviceIdentity;
    next();
};

// Request metrics middleware
const metricsMiddleware = (req, res, next) => {
    const end = httpRequestDuration.startTimer({
        method: req.method,
        route: req.route?.path || req.path,
        calling_service: req.callingService,
    });

    res.on('finish', () => {
        end({ status_code: res.statusCode });
    });

    next();
};

app.use(metricsMiddleware);

// East-West API endpoint
app.get('/internal/customers/:customerId', authenticateService, async (req, res) => {
    const startTime = Date.now();
    const traceId = req.headers['x-trace-id'] || generateTraceId();

    try {
        const { customerId } = req.params;
        const { includeInternal = false } = req.query;

        // Service-to-service business logic
        const customer = await customerService.getCustomerById(customerId, {
            includeDeleted: false,
            includeInternalFields: includeInternal,
        });

        if (!customer) {
            return res.status(404).json({
                error: 'Customer not found',
                errorCode: 'CUSTOMER_NOT_FOUND',
                traceId,
                customerId,
            });
        }

        // Internal response format with additional metadata
        const responseData = {
            id: customer.id,
            email: customer.email,
            status: customer.status,
            createdAt: customer.createdAt,
            updatedAt: customer.updatedAt,
            version: customer.version,
            ...(includeInternal && {
                internalMetadata: {
                    riskScore: customer.riskScore,
                    segmentId: customer.segmentId,
                    lastActivityAt: customer.lastActivityAt,
                    flags: customer.flags,
                },
            }),
        };

        // Add service performance metrics
        res.set('X-Service-Response-Time', `${Date.now() - startTime}ms`);
        res.set('X-Trace-Id', traceId);
        res.set('X-Service-Version', process.env.SERVICE_VERSION || '1.0.0');

        res.json(responseData);
    } catch (error) {
        console.error('East-West API Error:', {
            error: error.message,
            stack: error.stack,
            customerId: req.params.customerId,
            callingService: req.callingService,
            traceId,
        });

        res.status(500).json({
            error: 'Internal service error',
            errorCode: 'INTERNAL_SERVICE_ERROR',
            traceId,
            timestamp: new Date().toISOString(),
        });
    }
});

// Bulk operations endpoint for service-to-service efficiency
app.post('/internal/customers/batch', authenticateService, async (req, res) => {
    const traceId = req.headers['x-trace-id'] || generateTraceId();

    try {
        const { customerIds, fields = [] } = req.body;

        if (!Array.isArray(customerIds) || customerIds.length === 0) {
            return res.status(400).json({
                error: 'Customer IDs array is required',
                errorCode: 'INVALID_CUSTOMER_IDS',
                traceId,
            });
        }

        if (customerIds.length > 1000) {
            return res.status(400).json({
                error: 'Maximum 1000 customer IDs per request',
                errorCode: 'TOO_MANY_CUSTOMER_IDS',
                traceId,
            });
        }

        const customers = await customerService.getCustomersByIds(customerIds, {
            fields: fields.length > 0 ? fields : undefined,
            callingService: req.callingService,
        });

        res.set('X-Trace-Id', traceId);
        res.json({
            customers,
            requestedCount: customerIds.length,
            foundCount: customers.length,
            processingTimeMs: Date.now() - startTime,
        });
    } catch (error) {
        console.error('East-West Batch API Error:', {
            error: error.message,
            callingService: req.callingService,
            traceId,
        });

        res.status(500).json({
            error: 'Batch operation failed',
            errorCode: 'BATCH_OPERATION_ERROR',
            traceId,
        });
    }
});

// Health check for service mesh
app.get('/health', (req, res) => {
    res.status(200).json({
        status: 'healthy',
        service: 'customer-service',
        version: process.env.SERVICE_VERSION || '1.0.0',
        timestamp: new Date().toISOString(),
    });
});

// Metrics endpoint for Prometheus
app.get('/metrics', async (req, res) => {
    res.set('Content-Type', register.contentType);
    const metrics = await register.metrics();
    res.end(metrics);
});

// HTTPS server with mTLS for East-West communication
const httpsOptions = {
    key: fs.readFileSync('/etc/ssl/private/service.key'),
    cert: fs.readFileSync('/etc/ssl/certs/service.crt'),
    ca: fs.readFileSync('/etc/ssl/certs/ca.crt'),
    requestCert: true,
    rejectUnauthorized: true,
};

const server = https.createServer(httpsOptions, app);

server.listen(8443, () => {
    console.log('East-West API server running on port 8443 with mTLS');
});

function generateTraceId() {
    return (
        Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15)
    );
}
