#### 5.1.1 Functional Testing

```javascript
// North-South API Test Suite
const request = require('supertest');
const jwt = require('jsonwebtoken');

describe('North-South Customer API', () => {
    let validToken;
    let invalidToken;

    beforeAll(() => {
        validToken = jwt.sign(
            { userId: 'test-user-123', role: 'customer' },
            process.env.JWT_SECRET,
            {
                expiresIn: '1h',
            }
        );
        invalidToken = 'invalid.token.here';
    });

    describe('Authentication Tests', () => {
        test('should reject requests without token', async () => {
            const response = await request(app).get('/api/v1/customers').expect(401);

            expect(response.body).toMatchObject({
                error: 'Access token required',
                errorCode: 'AUTH_TOKEN_MISSING',
            });
        });

        test('should reject requests with invalid token', async () => {
            const response = await request(app)
                .get('/api/v1/customers')
                .set('Authorization', `Bearer ${invalidToken}`)
                .expect(403);

            expect(response.body).toMatchObject({
                error: 'Invalid access token',
                errorCode: 'AUTH_TOKEN_INVALID',
            });
        });

        test('should accept requests with valid token', async () => {
            const response = await request(app)
                .get('/api/v1/customers')
                .set('Authorization', `Bearer ${validToken}`)
                .expect(200);

            expect(response.body).toHaveProperty('data');
            expect(response.body).toHaveProperty('meta');
        });
    });

    describe('Rate Limiting Tests', () => {
        test('should apply rate limiting to external requests', async () => {
            const requests = Array.from({ length: 101 }, (_, i) =>
                request(app).get('/api/v1/customers').set('Authorization', `Bearer ${validToken}`)
            );

            const responses = await Promise.all(requests);
            const rateLimitedResponses = responses.filter((r) => r.status === 429);

            expect(rateLimitedResponses.length).toBeGreaterThan(0);
            expect(rateLimitedResponses[0].body).toMatchObject({
                message: 'Too many requests from this IP, please try again later.',
            });
        });
    });

    describe('Data Format Tests', () => {
        test('should return user-friendly response format', async () => {
            const response = await request(app)
                .get('/api/v1/customers')
                .set('Authorization', `Bearer ${validToken}`)
                .expect(200);

            expect(response.body.data).toBeInstanceOf(Array);
            expect(response.body.meta).toMatchObject({
                page: expect.any(Number),
                limit: expect.any(Number),
                total: expect.any(Number),
                hasNextPage: expect.any(Boolean),
            });

            // Ensure no internal fields are exposed
            if (response.body.data.length > 0) {
                const customer = response.body.data[0];
                expect(customer).not.toHaveProperty('internalMetadata');
                expect(customer).not.toHaveProperty('riskScore');
                expect(customer).not.toHaveProperty('segmentId');
            }
        });
    });
});
