#### 5.1.2 Security Testing

```javascript
// Security Test Suite for North-South APIs
describe('North-South API Security', () => {
    describe('Input Validation', () => {
        test('should validate query parameters', async () => {
            const response = await request(app)
                .get('/api/v1/customers?limit=invalid')
                .set('Authorization', `Bearer ${validToken}`)
                .expect(400);

            expect(response.body).toMatchObject({
                error: expect.stringContaining('Invalid limit parameter'),
                errorCode: 'VALIDATION_ERROR',
            });
        });

        test('should sanitize SQL injection attempts', async () => {
            const maliciousQuery = "1'; DROP TABLE customers; --";

            const response = await request(app)
                .get(`/api/v1/customers?search=${encodeURIComponent(maliciousQuery)}`)
                .set('Authorization', `Bearer ${validToken}`)
                .expect(400);

            expect(response.body).toMatchObject({
                error: expect.stringContaining('Invalid search parameter'),
                errorCode: 'VALIDATION_ERROR',
            });
        });
    });

    describe('CORS and Security Headers', () => {
        test('should include security headers', async () => {
            const response = await request(app)
                .get('/api/v1/customers')
                .set('Authorization', `Bearer ${validToken}`)
                .expect(200);

            expect(response.headers).toMatchObject({
                'x-content-type-options': 'nosniff',
                'x-frame-options': 'DENY',
                'x-xss-protection': '1; mode=block',
            });
        });
    });
});
