#### 5.2.1 Service-to-Service Testing

```javascript
// East-West API Test Suite
const https = require('https');
const fs = require('fs');

describe('East-West Customer Service API', () => {
    let httpsAgent;

    beforeAll(() => {
        // Setup mTLS client for testing
        httpsAgent = new https.Agent({
            key: fs.readFileSync('/test/certs/client.key'),
            cert: fs.readFileSync('/test/certs/client.crt'),
            ca: fs.readFileSync('/test/certs/ca.crt'),
            rejectUnauthorized: true,
        });
    });

    describe('Service Authentication', () => {
        test('should require valid client certificate', async () => {
            // Test without client certificate
            const invalidAgent = new https.Agent({
                rejectUnauthorized: false,
            });

            try {
                await request
                    .agent(app, { httpsAgent: invalidAgent })
                    .get('/internal/customers/test-123')
                    .expect(401);
            } catch (error) {
                expect(error.code).toBe('ECONNRESET');
            }
        });

        test('should accept valid service certificate', async () => {
            const response = await request
                .agent(app, { httpsAgent })
                .get('/internal/customers/test-customer-123')
                .set('X-Trace-Id', 'test-trace-123')
                .expect(200);

            expect(response.body).toHaveProperty('id');
            expect(response.body).toHaveProperty('version');
            expect(response.headers['x-trace-id']).toBe('test-trace-123');
        });
    });

    describe('Performance Requirements', () => {
        test('should respond within performance SLA', async () => {
            const startTime = Date.now();

            const response = await request
                .agent(app, { httpsAgent })
                .get('/internal/customers/test-customer-123')
                .set('X-Trace-Id', 'perf-test-123')
                .expect(200);

            const responseTime = Date.now() - startTime;

            // East-West APIs should be high-performance
            expect(responseTime).toBeLessThan(100); // 100ms SLA
            expect(response.headers['x-service-response-time']).toBeDefined();
        });

        test('should handle batch operations efficiently', async () => {
            const customerIds = Array.from({ length: 100 }, (_, i) => `customer-${i}`);

            const startTime = Date.now();
            const response = await request
                .agent(app, { httpsAgent })
                .post('/internal/customers/batch')
                .send({ customerIds })
                .set('X-Trace-Id', 'batch-test-123')
                .expect(200);

            const responseTime = Date.now() - startTime;

            expect(responseTime).toBeLessThan(500); // 500ms for batch operation
            expect(response.body).toMatchObject({
                requestedCount: 100,
                foundCount: expect.any(Number),
                processingTimeMs: expect.any(Number),
            });
        });
    });

    describe('Internal Data Exposure', () => {
        test('should expose internal metadata when requested', async () => {
            const response = await request
                .agent(app, { httpsAgent })
                .get('/internal/customers/test-customer-123?includeInternal=true')
                .set('X-Trace-Id', 'metadata-test-123')
                .expect(200);

            expect(response.body).toHaveProperty('internalMetadata');
            expect(response.body.internalMetadata).toMatchObject({
                riskScore: expect.any(Number),
                segmentId: expect.any(String),
                lastActivityAt: expect.any(String),
                flags: expect.any(Array),
            });
        });

        test('should include service metadata in responses', async () => {
            const response = await request
                .agent(app, { httpsAgent })
                .get('/internal/customers/test-customer-123')
                .set('X-Trace-Id', 'service-metadata-test-123')
                .expect(200);

            expect(response.headers).toMatchObject({
                'x-service-version': expect.any(String),
                'x-service-response-time': expect.stringMatching(/\d+ms/),
                'x-trace-id': 'service-metadata-test-123',
            });
        });
    });
});
